const main=document.querySelector('main'),states=document.querySelector('#state');
const a=(to,text,cls='outline')=>`<a class="${cls}" href="#${to}">${text}</a>`;
const notice=(text,type='')=>`<div class="notice ${type}" role="${type==='error'?'alert':'status'}">${text}</div>`;
const pages={
home:()=>`<section class="hero"><div><div class="eyebrow">مسیر راه سرمایه‌گذاری</div><h1>بازار را بفهمید؛<br>مسیر یادگیری‌تان را ادامه دهید.</h1><p class="lead">یک دورهٔ فصلی با وبینار و سه ماه همراهی در مسیر راه سرمایه‌گذاری؛ محتوای دوره و داشبوردهای مجاز، در یک حساب.</p><div class="actions">${a('course','آشنایی با دوره','btn')}${a('consultation','درخواست وقت مشاوره')}</div><p class="meta">مشاورهٔ اختصاصی خدمت جداگانه‌ای است و با عضویت دوره فعال نمی‌شود.</p></div><aside class="course-cover"><div class="eyebrow">دورهٔ فصلی</div><h2>وبینار، شروع یک مسیر</h2><p>مرور بازار، موضوعات آموزشی و پرسش‌های شما؛ سپس ادامهٔ استفاده از منابع و محتوای مجاز دوره.</p><dl><div><dt>وبینار</dt><dd>رویدادی درون دوره</dd></div><div><dt>مدت همراهی</dt><dd>سه ماه</dd></div><div><dt>تاریخ و هزینه</dt><dd>هنوز اعلام نشده</dd></div></dl><div class="actions">${a('course','جزئیات و وضعیت ثبت‌نام','gold outline')}</div></aside></section><section><div class="section-head"><h2>از آشنایی تا استفاده از دوره</h2><span class="meta">همهٔ مراحل در حساب شما</span></div><div class="steps"><article><b>۰۱ · انتخاب دوره</b><p>موضوع، زمان و حدود دسترسی را پیش از ثبت‌نام ببینید.</p></article><article><b>۰۲ · ورود و نیازسنجی</b><p>ثبت‌نام معتبر را به حساب متصل کنید و هدف آموزشی‌تان را بنویسید.</p></article><article><b>۰۳ · ادامهٔ مسیر</b><p>وبینار، منابع و مطالب منتشرشده برای دوره را از خانهٔ عضو دنبال کنید.</p></article></div></section><section class="grid"><article class="panel"><div class="eyebrow">اطلاعات عمومی</div><h3>وضعیت بازار</h3><p>هر عدد همراه با واحد، منبع و زمان معتبر داده دیده می‌شود.</p>${a('market','بازکردن نمای بازار')}</article><article class="panel"><div class="eyebrow">اعضای دوره</div><h3>خانهٔ عضو</h3><p>دوره‌های شما، حدود دسترسی و اقدام بعدی در یک صفحه.</p>${a('member','دیدن نمونهٔ خانهٔ عضو')}</article><article class="panel"><div class="eyebrow">خدمت مستقل</div><h3>وقت مشاوره</h3><p>موضوع و زمان‌های مناسب را برای پیگیری درخواست مشخص کنید.</p>${a('consultation','دیدن مسیر درخواست')}</article></section>`,
course:()=>`<div class="eyebrow">دورهٔ فصلی · مسیر راه سرمایه‌گذاری</div><h1>وبینار و سه ماه همراهی</h1><p class="lead">وبینار یکی از رویدادهای دوره است. عضویت، دسترسی به محتوا و ابزارهای انتخاب‌شدهٔ همان دوره را در مدت مشخص ایجاد می‌کند.</p>${notice('تاریخ شروع و پایان، زمان وبینار، هزینه و سامانهٔ ثبت‌نام هنوز اعلام نشده‌اند.')}<section class="layout" style="margin-top:24px"><div><article class="panel"><h2>در دوره چه می‌بینید؟</h2><ul class="list"><li><h3>وبینار تحلیل بازار</h3><p>مرور وضعیت بازار و پرسش و پاسخ. زمان و روش حضور پس از اعلام در این صفحه مشخص می‌شود.</p></li><li><h3>مسیر راه سرمایه‌گذاری</h3><p>مطالب منتشرشده برای اعضای دوره و منابع مجاز، در سایت و کانال دوره.</p></li><li><h3>داشبوردهای منتخب</h3><p>فقط نماهایی که برای این دوره فعال شده‌اند؛ همهٔ ابزارهای تخصصی میز آرش در دسترس اعضا نیستند.</p></li></ul></article><article class="panel" style="margin-top:24px"><h2>پیش از ثبت‌نام</h2><p>شروع و پایان دقیق دسترسی باید اعلام شود. در ثبت‌نام دیرهنگام، مدت باقی‌مانده را پیش از تأیید ببینید.</p><p>دسترسی به ضبط و منابع پس از پایان دوره، تابع شرایط همان دوره است. پایان عضویت، پرونده و اطلاعات شخصی شما را حذف نمی‌کند.</p><p class="meta">شرایط نهایی مدت دسترسی و آرشیو، پس از اعلام در همین صفحه نمایش داده می‌شود.</p></article></div><aside><article class="panel"><h2>وضعیت دوره</h2><dl><div><dt>شروع / پایان</dt><dd>اعلام نشده</dd></div><div><dt>زمان وبینار</dt><dd>اعلام نشده</dd></div><div><dt>هزینه</dt><dd>اعلام نشده</dd></div></dl><button disabled style="width:100%;margin-top:24px" aria-describedby="registration-help">ثبت‌نام هنوز باز نشده</button><p id="registration-help" class="hint">مقصد بیرونی پس از تأیید سامانه و شرایط ثبت‌نام نمایش داده می‌شود.</p></article><article class="panel" style="margin-top:24px"><h3>قبلاً ثبت‌نام کرده‌اید؟</h3><p>پس از ورود، وضعیت اتصال ثبت‌نام به حساب را بررسی کنید.</p>${a('member','بررسی نمونهٔ حساب')}</article></aside></section>`,
member:()=>{const state=states.value;const status={active:'فعال · نمونهٔ نمایشی',empty:'بدون عضویت',error:'دریافت ناموفق',expired:'منقضی',incomplete:'عضویت فعال · اطلاعات ناقص',scheduled:'شروع نشده',revoked:'لغوشده',unknown:'وضعیت نامشخص',two:'دو عضویت مستقل'}[state];let body='';if(state==='error')body=notice('وضعیت عضویت دریافت نشد. این خطا به معنی پایان دسترسی نیست. دوباره تلاش کنید.','error')+'<div class="actions"><button id="retry">تلاش دوباره در نمونه</button></div>';else if(state==='empty')body='<div class="empty"><h2>هنوز دوره‌ای به این حساب متصل نیست</h2><p>اگر ثبت‌نام کرده‌اید، اتصال حساب را پیگیری کنید. ورود به حساب، عضویت ایجاد نمی‌کند.</p><div class="actions">'+a('course','دیدن دوره')+a('link','بررسی اتصال ثبت‌نام')+'</div></div>';else if(state==='unknown')body=notice('وضعیت عضویت هنوز قابل تأیید نیست. محتوا تا پاسخ معتبر سامانه باز نمی‌شود.')+a('link','پیگیری اتصال حساب');else body=`${state==='incomplete'?notice('برای آماده‌سازی محتوای آموزشی، نیازسنجی کوتاه را تکمیل کنید. پاسخ‌ها قابل اصلاح‌اند.'):''}<section class="grid two" style="margin-top:24px"><article class="panel"><div class="row"><h2>دورهٔ نمونهٔ A</h2><span class="tag ${state==='expired'||state==='revoked'?'warn':'active'}">${status}</span></div><dl><div><dt>بازهٔ نمونه، تهران</dt><dd>۱ اکتبر تا ۱ ژانویه · ساعت ۹ تهران</dd></div><div><dt>سال‌های نمونه</dt><dd>۲۰۲۶ / ۲۰۲۷</dd></div></dl><p class="hint">این بازه یک مثال قراردادی است؛ تاریخ وبینار واقعی نیست. دسترسی در ساعت پایان تمام می‌شود.</p>${state==='expired'?notice('دسترسی دورهٔ A پایان یافته است. اطلاعات شخصی و نیازسنجی شما محفوظ است. شرایط آرشیو باید برای همین دوره اعلام شود.'):state==='revoked'?notice('عضویت دورهٔ A لغو شده است. دلیل و مرجع پیگیری در حساب واقعی نمایش داده خواهد شد.'):state==='scheduled'?notice('این دوره هنوز شروع نشده است. محتوای محدودشده تا شروع باز نمی‌شود.'):a('content','محتوا و منابع دوره','btn')}</article><article class="panel"><h2>اقدام بعدی</h2><p>${state==='expired'?'شرایط دورهٔ بعد را بررسی کنید. تمدید خودکار فعال فرض نشده است.':state==='revoked'?'وضعیت لغو را پیگیری کنید؛ ثبت‌نام یا پرداخت به‌تنهایی دسترسی را برنمی‌گرداند.':state==='scheduled'?'پرسش وبینار و هدف آموزشی را ثبت کنید.':'هدف آموزشی و پرسش وبینار را بنویسید یا اصلاح کنید.'}</p><div class="actions">${a('needs','نیازسنجی آموزشی')}${a('course','جزئیات دوره')}</div></article></section>${state==='two'?'<article class="panel"><h2>دورهٔ نمونهٔ B · فعال</h2><p>بازهٔ نمونه: ۱ دسامبر ۲۰۲۶ تا ۱ مارس ۲۰۲۷، ساعت ۹ تهران. عضویت B مستقل از A است.</p>'+a('content','محتوای مجاز دورهٔ B','btn')+'</article>':''}`;return `<div class="eyebrow">حساب شما · نمونهٔ نمایشی</div><h1>خانهٔ عضو</h1><p class="lead">وضعیت هر دوره، محتوا و اقدام بعدی را جدا ببینید.</p>${body}<section class="grid two" style="margin-top:32px"><article class="panel"><h2>پروندهٔ شخصی</h2><p>اطلاعات شخصی با پایان عضویت دوره حذف نمی‌شود. این نمونه، پروندهٔ واقعی را نمایش نمی‌دهد.</p><span class="tag">پروندهٔ واقعی در prototype متصل نیست</span></article><article class="panel"><h2>مشاورهٔ مستقل</h2><p>درخواست وقت با رزرو تأییدشده متفاوت است. مشاهدهٔ پرونده توسط مشاور، رضایت جداگانه دارد.</p>${a('consultation','درخواست وقت مشاوره')}</article></section>`},
needs:()=>`<div class="eyebrow">نیازسنجی آموزشی · نمونهٔ نمایشی</div><h1>برای چه موضوعی همراه دوره هستید؟</h1><p class="measure">این پرسش‌ها برای شناخت هدف آموزشی است. ارزیابی تخصصی ریسک مالی نیست.</p><form id="needs-form" class="panel measure"><div class="field"><label for="experience">تجربهٔ آشنایی با سرمایه‌گذاری</label><select id="experience"><option>تازه شروع کرده‌ام</option><option>تجربهٔ محدود دارم</option><option>مدتی است پیگیری می‌کنم</option><option>ترجیح می‌دهم پاسخ ندهم</option></select></div><div class="field"><label for="interest">موضوع مورد علاقه</label><select id="interest"><option>شناخت صندوق‌ها</option><option>شناخت بازار سهام</option><option>طلا و ارز</option><option>اصول مدیریت مالی</option></select></div><div class="field"><label for="goal">هدف آموزشی (ضروری)</label><input id="goal" required maxlength="500" placeholder="مثلاً فهم تفاوت انواع صندوق"><p class="hint">برای نمونه، از اطلاعات شخصی یا مالی واقعی استفاده نکنید.</p></div><div class="field"><label for="question">پرسش شما برای وبینار (اختیاری)</label><textarea id="question" maxlength="1000"></textarea></div><button class="btn">ذخیرهٔ محلی نمونه</button><p id="save-result" role="status"></p></form><div class="actions">${a('member','بازگشت به خانهٔ عضو')}</div>`,
consultation:()=>`<div class="eyebrow">خدمت مستقل از دوره</div><h1>درخواست وقت مشاوره</h1><p class="lead">موضوع و زمان‌های مناسب را مشخص کنید. ثبت درخواست به معنی رزرو جلسه نیست؛ زمان قطعی پس از پیگیری و تأیید طرفین اعلام می‌شود.</p><div class="layout"><article class="panel"><h2>اطلاعات لازم برای پیگیری</h2><ul><li>نام و راه تماس تأییدشده</li><li>موضوع جلسه و شرح کوتاه</li><li>بازه‌های زمانی مناسب با ساعت تهران</li><li>اجازهٔ تماس برای پیگیری همین درخواست</li></ul><p>اشتراک‌گذاری پروندهٔ مالی رضایت مستقل دارد و در این مرحله خودکار فعال نمی‌شود.</p><button disabled aria-describedby="consult-help">ارسال واقعی در این نمونه فعال نیست</button><p id="consult-help" class="hint">مسیر موجود عمومی: <a href="https://portfolio-platform-fawn.vercel.app/#waitlist">فرم درخواست در سایت</a>. این نمونه تغییری در آن فرم ایجاد نمی‌کند.</p></article><aside class="panel"><h2>وضعیت پیگیری</h2><div class="timeline"><p><b>درخواست دریافت‌شده</b><br><span class="meta">منتظر بررسی؛ بدون جلسهٔ قطعی</span></p><p><b>نیازمند هماهنگی</b><br><span class="meta">بازه‌های زمانی در حال تطبیق</span></p><p><b>رزرو تأییدشده</b><br><span class="meta">فقط با زمان، منطقهٔ زمانی و تأیید صریح</span></p></div><span class="tag">مراحل نمونه؛ رزرو فعلی وجود ندارد</span></aside></div>`,
link:()=>`<h1>اتصال ثبت‌نام به حساب</h1>${notice('هیچ اطلاعاتی در این نمونه ارسال نمی‌شود. ثبت‌نام بیرونی باید با روش تأییدشده به حساب فعلی متصل شود.')}<article class="panel" style="margin-top:24px"><h2>حساب نامرتبط</h2><p>ثبت‌نام به این حساب متصل نشده است. برای حفظ دسترسی صاحب ثبت‌نام، عضویت خودکار اعطا نمی‌شود.</p><p>سامانهٔ ثبت‌نام هنوز مشخص نیست. راه تأیید مالکیت و مسیر پیگیری پس از مشخص‌شدن سامانهٔ ثبت‌نام ارائه می‌شود.</p>${a('member','برگشت به وضعیت حساب')}</article>`,
content:()=>`<div class="eyebrow">محتوا و منابع · نمونهٔ نمایشی</div><h1>ادامهٔ مسیر دوره</h1>${notice('این صفحه نمونهٔ طراحی است و کنترل دسترسی اجرایی ندارد. نسخهٔ واقعی هر درخواست را سمت سرور بررسی می‌کند.')}<section class="grid" style="margin-top:24px"><article class="panel"><h2>وبینار دوره</h2><p>زمان رویداد هنوز اعلام نشده است.</p><button disabled>ورود به وبینار پس از اعلام</button></article><article class="panel"><h2>مطالب دوره</h2><p>هنوز مطلبی برای این نمونه منتشر نشده است.</p><span class="tag">خالی</span></article><article class="panel"><h2>داشبوردهای مجاز</h2><p>ماژول‌های فعال دوره از مجوزهای همین عضویت می‌آیند.</p>${a('market','دیدن الگوی بازار')}</article></section>${a('member','بازگشت به خانهٔ عضو')}`,
market:()=>`<div class="eyebrow">نمای عمومی · الگوی تراکم داده</div><h1>وضعیت بازار</h1>${notice('دادهٔ بازار ایران در دسترس نیست. زمان معتبر داده و آخرین دریافت: نامشخص. این وضعیت به معنی تعطیلی یا آرام‌بودن بازار نیست.','error')}<section class="grid" style="margin-top:24px"><article class="panel"><h2>شاخص کل</h2><p>—</p><span class="meta">دادهٔ معتبر در دسترس نیست</span></article><article class="panel"><h2>ارزش معاملات</h2><p>— تومان</p><span class="meta">از نبود داده، مقدار صفر نتیجه نمی‌شود</span></article><article class="panel"><h2>خالص پول حقیقی</h2><p>— تومان</p><span class="meta">پوشش منبع مشخص نیست</span></article></section><h2>صندوق‌ها</h2><p>ردیف‌های زیر صرفاً نمونهٔ طراحی هستند و قیمت واقعی ندارند.</p><div class="table-wrap" tabindex="0" aria-label="جدول صندوق‌ها، در موبایل افقی قابل پیمایش"><table><caption>نمونهٔ نمایشی · قیمت و NAV در تومان</caption><thead><tr><th scope="col">نماد</th><th scope="col">قیمت</th><th scope="col">NAV معتبر</th><th scope="col">فاصله با NAV</th><th scope="col">تاریخ معتبر</th><th scope="col">دلیل وضعیت</th></tr></thead><tbody><tr><th scope="row">صندوق نمونه A</th><td class="numeric">—</td><td class="numeric">—</td><td class="numeric">—</td><td>نامشخص</td><td>دریافت ناموفق</td></tr><tr><th scope="row">صندوق نمونه B</th><td class="numeric">—</td><td class="numeric">—</td><td class="numeric">—</td><td>نامشخص</td><td>NAV معتبر موجود نیست</td></tr></tbody></table></div><p class="hint">موبایل: جدول داخل قاب پیمایش می‌شود؛ بدنهٔ صفحه نباید افقی جابه‌جا شود. ستون نماد، وضعیت و واحد همیشه قابل فهم است.</p><div class="actions">${a('home','بازگشت به صفحهٔ اصلی')}</div>`,
desk:()=>`<div class="eyebrow">نمای داخلی آرش · نمونهٔ نمایشی</div><h1>میز روزانهٔ آرش</h1><p class="lead">ابتدا موارد نیازمند رسیدگی؛ سپس شواهد، پژوهش و انتشار برای مخاطب مشخص.</p><section class="grid"><article class="panel"><h2>دادهٔ بازار</h2><span class="tag danger">دریافت نامشخص</span><p>سلامت سرور با معتبر بودن داده متفاوت است.</p></article><article class="panel"><h2>دوره‌ها</h2><span class="tag">صف نمونه</span><p>ثبت‌نام، اتصال حساب و مدت دسترسی، جدا از پرداخت.</p></article><article class="panel"><h2>انتشار</h2><span class="tag warn">منتظر بازبینی</span><p>تأیید، انتشار و تحویل اعلان سه وضعیت مستقل‌اند.</p></article></section><div class="table-wrap" tabindex="0" aria-label="صف رسیدگی نمونه"><table class="dense"><caption>صف رسیدگی · همهٔ موارد مصنوعی‌اند</caption><thead><tr><th scope="col">مورد</th><th scope="col">مخاطب / دوره</th><th scope="col">وضعیت</th><th scope="col">اقدام بعدی</th><th scope="col">شاهد</th></tr></thead><tbody><tr><th scope="row">ثبت‌نام نمونه A</th><td>دورهٔ A</td><td>حساب نامرتبط</td><td>تأیید مالکیت</td><td>مرجع بیرونی مجهول</td></tr><tr><th scope="row">پژوهش نمونه B</th><td>داخلی</td><td>پیش‌نویس</td><td>بازبینی نسخه</td><td>نسخهٔ نمونه</td></tr><tr><th scope="row">انتشار نمونه C</th><td>اعضای دوره B</td><td>تأیید نشده</td><td>انتخاب مخاطب و تأیید</td><td>انتشار واقعی ندارد</td></tr></tbody></table></div><p class="hint">ردیف ۴۴ پیکسل و متن ۱۴ پیکسل؛ روی موبایل جزئیات به صفحهٔ مورد منتقل شود. هیچ پروندهٔ خصوصی در نمای عمومی ظاهر نمی‌شود.</p>${a('member','نمونهٔ نمای عضو')}`
};
function render(moveFocus=false){const route=location.hash.slice(1)||'home';main.innerHTML=(pages[route]||pages.home)();document.title=`${main.querySelector('h1')?.textContent||'مسیر راه'} · نمونهٔ طراحی`;document.querySelectorAll('nav a').forEach(el=>{if(el.hash===location.hash)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});if(moveFocus)main.focus();document.querySelector('#retry')?.addEventListener('click',()=>{states.value='active';render(true)});const form=document.querySelector('#needs-form');if(form){const saved=JSON.parse(localStorage.getItem('next03-demo-needs')||'null');if(saved)for(const key of ['experience','interest','goal','question'])document.getElementById(key).value=saved[key];form.addEventListener('submit',e=>{e.preventDefault();const data={};for(const key of ['experience','interest','goal','question'])data[key]=document.getElementById(key).value;localStorage.setItem('next03-demo-needs',JSON.stringify(data));document.querySelector('#save-result').textContent='پاسخ نمونه فقط در همین مرورگر ذخیره شد؛ می‌توانید آن را اصلاح کنید.'})}}
window.addEventListener('hashchange',()=>render(true));states.addEventListener('change',()=>render(false));render();


